            "adv_portfolio_h3_474_html": "<span style=\"font-size: 1.5rem;\">⚔️</span> 4. RPG Engine",
            "adv_portfolio_h3_476_html": "🔥 5. The Mini Framework",
            "adv_portfolio_li_464_html": "Scan je assembly met <strong>Reflection</strong>.",
            "adv_portfolio_li_465_html": "Vind methods met jouw eigen `[MyTest]` attribute.",
            "adv_portfolio_li_466_html": "Voer ze uit en vang exceptions op.",
            "adv_portfolio_p_458_html": "Dit zijn de 5 \"Boss Battles\". Voltooi deze projecten om je <span style=\"color: var(--accent);\">Senior Status</span> te verdienen.",
            "adv_portfolio_p_459": "Elke pro bouwt zijn eigen tools. Maak een `git`-kloon of een file-processor.",
            "adv_portfolio_p_460": "Snap je recursie echt? Bouw een boomstructuur van mappen en bestanden in het geheugen.",
            "adv_portfolio_p_461": "De echte wereld draait op API's. Haal data op (Crypto/Weer) en verwerk het.",
            "adv_portfolio_p_462": "OOP op zijn best. Classes, Inheritance, Polymorphism en State Management.",
            "adv_portfolio_p_463_html": "De ultieme test. Bouw je eigen Unit Test runner of Dependency Injection container.",
