            "hero_cmd": "> dotnet new career --level senior",
            "hero_desc_html": "Vergeet simpele tutorials. Leer hoe C# <strong>fysiek</strong> werkt in het geheugen, van CPU-register tot Garbage Collector.",
            "hero_title": "C# Console Masterclass",
            "m22_alert_strong": "⚠️ Valkuil:",
            "m22_alert_text": "Maak structs <strong>Immutable</strong> (onveranderlijk). Mutable structs zijn de bron van vreselijke bugs omdat je steeds kopieën aanpast in plaats van het origineel.",
            "m22_em1": "*Er bestaat ook `record struct`, maar dat is advanced.",
            "m22_h2_1": "1. Class (Reference Type)",
            "m22_h2_2": "2. Struct (Value Type)",
            "m22_h2_3": "3. Record (Reference Type*)",
            "m22_h2_decision": "Beslisboom",
            "m22_lead": "C# geeft je drie smaken om data te modelleren. Wanneer kies je welke?",
            "m22_p1": "De standaard. 90% van je code zal classes zijn. Ze leven op de Heap en ondersteunen overerving (Inheritance).",
            "m22_p2": "Voor kleine, atomische data die zich gedraagt als een getal. Leeft op de Stack (als local var) of inline in een array.",
            "m22_p3": "Nieuw in C# 9. Records zijn classes, maar met <strong>Value Semantics</strong> voor gelijkheid.",
            "m22_p4": "Records zijn perfect voor <strong>DTO's (Data Transfer Objects)</strong>: simpele pakketjes data zonder gedrag.",
            "m22_td_1": "Heeft het een identiteit? (zoals een User in database)",
            "m22_td_2": "Is het alleen data om door te sturen? (API response)",
            "m22_td_3": "Is het kleiner dan 16 bytes, onveranderlijk en 'wiskundig'?",
            "m22_th_choice": "Kies...",
