            "tut_syntax_h3_5": "1. Statements eindigen met <code>;</code>",
            "tut_syntax_h3_8": "2. Case-Sensitive (Hoofdlettergevoelig)",
            "tut_syntax_p_11": "Code die bij elkaar hoort (bijv. in een `if` of `loop`) staat tussen accolades.",
            "tut_syntax_p_143": "1. Regel 1 mist een puntkomma <code>;</code><br> 2. Regel 2 gebruikt kleine letters voor <code>console</code> en <code>writeline</code> (Moet <code>Console.WriteLine</code> zijn). </p>",
            "tut_syntax_p_2": "C# is streng. Als je een puntkomma vergeet, stopt alles met werken.",
