            "tut_variables_deep_dive_text": "Wanneer gebruik je `var`? De regel is simpel: Gebruik het alleen als de rechterkant van de vergelijking <strong>overduidelijk</strong> maakt wat het type is.",
            "tut_variables_deep_dive_title": "Deep Dive: `var` vs Explicit Typing",
            "tut_variables_div_162": "🧠 Oefening",
            "tut_variables_extra_task_text": "Stel je hebt `int a = 10;` en `int b = 20;`. Schrijf code om de waardes om te wisselen zodat `a` 20 wordt en `b` 10. Je mag de getallen niet direct toewijzen!",
            "tut_variables_extra_task_title": "🔥 Extra Challenge: The Swap",
            "tut_variables_h1_151": "C# Variables",
            "tut_variables_h2_152": "Een variabele maken",
