            "tut_variables_h2_154": "Constants",
            "tut_variables_h2_155": "Naamgeving (Naming Conventions)",
            "tut_variables_li_161": "<strong>camelCase</strong> (voor lokale variabelen): <code>mijnNaam</code>, <code>aantalKlanten</code>",
            "tut_variables_li_2": "<strong>PascalCase</strong> (voor Classes en Methods): <code>BerekenTotaal()</code>, <code>KlantService</code>",
            "tut_variables_li_3": "Gebruik <strong>Engels</strong> in professionele code (wij gebruiken hier NL voor de uitleg).",
            "tut_variables_p_156": "Variabelen zijn containers ('doosjes') om data in op te slaan.",
            "tut_variables_p_157": "In C# moet je altijd vertellen <strong>wat</strong> er in de doos zit (het Type) en <strong>hoe</strong> hij heet (de Naam).",
            "tut_variables_p_158": "Als de compiler zelf kan raden wat het type is, mag je <code>var</code> gebruiken.",
            "tut_variables_p_159": "Als een waarde nooit mag veranderen, gebruik je <code>const</code>.",
            "tut_variables_p_160": "In C# zijn we streng over hoe je dingen noemt:",
            "tut_variables_p_4": "Maak een variabele voor de temperatuur (20.5 graden) en print deze.",
            "tut_variables_pro_tip_title": "🚀 Senior Pro Tip: Naming",
