            "tut_while_deep_dive_text": "In games en tools programma's zie je vaak een `while(true)` loop. Dit werkt als het \"hart\" van je programma dat blijft kloppen tot je stopt.",
            "tut_while_deep_dive_title": "Deep Dive: De Input Loop Game Loop",
            "tut_while_extra_task_text": "Maak een programma dat blijft vragen om een wachtwoord (\"geheim\") tot de gebruiker het goed heeft. Gebruik een `do...while` loop!",
            "tut_while_extra_task_title": "🔥 Extra Challenge: Raad het Nummer (Retry)",
            "tut_while_h1_163": "C# While Loop",
            "tut_while_h2_164": "De While Loop",
            "tut_while_h2_165": "De Do-While Loop",
            "tut_while_h2_166": "Wanneer welke?",
            "tut_while_li_170": "<strong>While:</strong> Als je niet zeker weet of je überhaupt moet beginnen (b.v. een bestand lezen).",
            "tut_while_li_2": "<strong>Do-While:</strong> Als je zeker weet dat je 1x iets moet doen (b.v. input vragen aan user).",
