            "tut_json_intro": "Ontdek hoe je data uitwisselt met het razend populaire JSON formaat.",
            "tut_json_what_is": "Wat is JSON?",
            "tut_json_what_is_text": "JSON (JavaScript Object Notation) is dé standaard voor het uitwisselen van data op het web. Het is leesbaar voor mensen en makkelijk te parsen voor computers.",
            "tut_json_system_text": "System.Text.Json",
            "tut_json_system_text_desc": "In modern C# (.NET Core en nieuwer) gebruiken we de ingebouwde library `System.Text.Json`. Deze is supersnel en veilig.",
