            "tut_json_serialize_desc": "Om een C# object om te zetten naar een JSON string, gebruik je `JsonSerializer.Serialize`.",
            "tut_json_deserialize": "Deserialisatie (JSON -> Object)",
            "tut_json_deserialize_desc": "Om een JSON string terug om te zetten naar een C# object, gebruik je `JsonSerializer.Deserialize`.",
            "tut_json_files": "JSON & Bestanden",
            "tut_json_files_desc": "Vaak wil je instellingen of data opslaan in een .json bestand. Dit combineert `System.IO` met JSON.",
