            "tut_api_h1": "Web API's (HttpClient)",
            "tut_api_intro": "Verbind je applicatie met het internet en haal live data op.",
            "tut_api_what_is": "Wat is een API?",
            "tut_api_what_is_text": "Een API (Application Programming Interface) zorgt ervoor dat twee applicaties met elkaar kunnen praten. Meestal gebruiken we een **REST API** die JSON terugstuurt.",
            "tut_api_httpclient": "De HttpClient",
            "tut_api_httpclient_desc": "In C# gebruiken we de `HttpClient` class om requests te doen. LET OP: Dit is een \"zwaar\" object, gebruik het slim!",
            "tut_api_async": "Async & Await",
            "tut_api_async_desc": "Het internet is traag. Daarom zijn API calls altijd **asynchronous**. Je programma mag niet bevriezen terwijl je wacht op data.",
            "tut_api_get_request": "Voorbeeld: GET Request",
            "tut_api_get_request_desc": "Laten we data ophalen van een publieke API.",
            "tut_api_exercise_title": "🎯 Oefening: Crypto Checker",
            "tut_api_exercise_text": "Maak een console app die de huidige Bitcoin prijs ophaalt.",
            "tut_api_summary": "Toon Antwoord",
            "tut_col_h1_1": "C# Collections & LINQ",
            "tut_col_p_2": "Arrays zijn leuk, maar in het echt gebruik je Lists en LINQ. Dit is de \"Pro\" manier.",
            "tut_col_h2_3": "1. List<T> (De Flexibele Array)",
            "tut_col_p_4": "Een Array heeft een vaste grootte. Een `List` groeit automatisch mee. Bijna altijd gebruik je een List in plaats van een Array.",
            "tut_col_h2_5": "2. Dictionary<K, V> (Sleutel & Waarde)",
            "tut_col_p_6": "Soms wil je iets opzoeken, zoals een telefoonboek (Naam -> Nummer). Een Dictionary koppelt een unieke <strong>Key</strong> aan een <strong>Value</strong>.",
            "tut_col_h2_7": "3. LINQ (Superkrachten voor Data)",
            "tut_col_p_8": "LINQ (Language Integrated Query) laat je filteren en sorteren in één regel code. Stop met het schrijven van `foreach` loops voor zoekwerk!",
            "tut_col_callout_title": "🚀 Lambda Expressies ( => )",
            "tut_col_callout_text": "Zie je dat pijltje <code>c => c > 5</code>? Dat heet een <strong>Lambda</strong>. Het betekent: <em>\"Voor elk cijfer 'c', check of 'c' groter is dan 5\"</em>.",
            "tut_col_ex_title": "🎯 Oefening: De LINQ Meester",
            "tut_col_ex_text": "Je hebt een lijst met prijzen: `10.50, 5.00, 20.00, 3.50`. Gebruik LINQ om: <br>1. Alles onder de 10 euro te vinden. <br>2. Ze te sorteren van laag naar hoog.",
            "tut_col_ex_summary": "Toon Antwoord",
            "tut_syntax_h2_syn_sem": "Deep Dive: Syntax vs Semantics",
            "tut_syntax_p_syn_sem": "Dit is een belangrijk concept om te snappen voor je theorie-toetsen!",
            "tut_syntax_h3_syntax": "1. Syntax (De Grammatica)",
            "tut_syntax_p_syntax": "Dit zijn de harde regels van de taal. Als je dit fout doet, snapt de computer je niet en <strong>start je programma niet</strong> (Compiler Error). <br><em>Vb: Puntkomma vergeten, haakje vergeten.</em>",
            "tut_syntax_h3_semantics": "2. Semantics (De Betekenis)",
            "tut_syntax_p_semantics": "De code is volgens de regels \"goed\", maar het slaat nergens op. Het programma start wel, maar <strong>crasht of doet iets geks</strong> tijdens het draaien (Logic Error). <br><em>Vb: Een negatieve leeftijd, delen door nul.</em>",
            "tut_syntax_h4_error_syn": "❌ Syntax Error",
            "tut_syntax_h4_error_sem": "⚠️ Semantic Error"
