            "adv_portfolio_p_463_html": "The ultimate test. Build your own Unit Test runner or Dependency Injection container.",
            "adv_portfolio_li_464_html": "Scan your assembly with Reflection.",
            "adv_portfolio_li_465_html": "Find methods with your own `[MyTest]` attribute.",
            "adv_portfolio_li_466_html": "Execute them and catch exceptions.",
            "btn_final_challenge": "Start The Final Challenge",
            "tut_abstraction_h1_1": "C# Abstraction",
            "tut_abstraction_p_2": "Hide the details (Data Abstraction). Show only what is necessary.",
            "tut_abstraction_h2_3": "Abstract Classes",
            "tut_abstraction_p_4": "A class that...",
            "tut_abstraction_p_1": "You can now",
            "tut_arrays_h1_1": "C# Arrays",
            "tut_arrays_p_2": "Variables that can hold multiple values.",
            "tut_arrays_h2_3": "Creating an Array",
            "tut_arrays_p_4": "You must specify the size beforehand. This can NOT change later.",
            "tut_arrays_h2_2": "Index (Starts at 0)",
            "tut_arrays_p_index": "The first item is at position 0. This is the most common mistake by beginners.",
            "tut_arrays_div_6": "🧠 Array vs List",
            "tut_arrays_p_5": "When do you use an Array and when a List?",
            "tut_arrays_summary_5": "Show Answer",
            "tut_booleans_h1_1": "C# Booleans",
            "tut_booleans_p_2": "In programming, everything is ultimately true (True) or false (False).",
            "tut_booleans_h2_3": "The Basics",
            "tut_booleans_p_4": "A",
            "tut_booleans_h2_7": "Boolean Expressions",
            "tut_booleans_p_9": "You often get a boolean back when you compare something.",
            "tut_booleans_h2_8": "Real World Example",
            "tut_booleans_p_10": "In professional apps you often see this in configurations (\"Flags\").",
            "tut_booleans_div_14": "🧠 Exercise",
            "tut_booleans_p_11": "What value does it have?",
            "tut_booleans_summary_13": "Show Answer",
            "tut_break_continue_h1_1": "C# Break & Continue",
            "tut_break_continue_p_2": "Sometimes you want to stop or skip a loop early.",
