            "tut_switch_p_138": "Write a switch expression that chooses a color based on a status (\"Error\" -> Red, \"Success\" -> Green).",
            "tut_switch_summary_4": "Show Answer",
            "tut_syllabus_h1_140": "Course Overview (Syllabus)",
            "tut_syllabus_p_141": "Here is the complete overview of what you will learn in this Masterclass.",
            "tut_syntax_h1_1": "C# Syntax Rules",
            "tut_syntax_p_2": "C# is strict. If you forget a semicolon, everything stops working.",
            "tut_syntax_h2_3": "The Skeleton",
            "tut_syntax_p_7": "In older tutorials (before C# 9) you often see...",
            "tut_syntax_h2_4": "Important Rules",
            "tut_syntax_h3_5": "1. Statements end with",
            "tut_syntax_p_6": "Every command must be terminated. Just like a period in a sentence.",
            "tut_syntax_h3_8": "2. Case-Sensitive",
            "tut_syntax_h3_10": "3. Blocks with",
            "tut_syntax_p_11": "Code that belongs together (e.g., in an `if` or `loop`) is placed between braces.",
            "tut_syntax_div_145": "🧠 Find the error",
            "tut_syntax_summary_144": "Show Answer",
            "tut_syntax_p_143": "1. Line 1 is missing a semicolon (this is C# 10, so no `Main` method needed anymore)",
            "tut_tutorial_template_h1_1": "[Page Title]",
