            "hero_cmd": "> dotnet new career --level senior",
            "hero_desc_html": "ลืมบทเรียนง่ายๆ ไปได้เลย เรียนรู้วิธีที่ C# ทำงาน <strong>ทางกายภาพ</strong> ในหน่วยความจำ ตั้งแต่รีจิสเตอร์ CPU ไปจนถึง Garbage Collector",
