            "tut_syntax_p_2": "C# เข้มงวด ถ้าคุณลืมอัฒภาค (;) ทุกอย่างจะหยุดทำงาน",
            "tut_syntax_h2_3": "โครงกระดูก",
            "tut_syntax_p_7": "ในบทเรียนเก่าๆ (ก่อน C# 9) คุณมักจะเห็น...",
            "tut_syntax_h2_4": "กฎสำคัญ",
            "tut_syntax_h3_5": "1. คำสั่งจบด้วย",
            "tut_syntax_p_6": "ทุกคำสั่งต้องปิดท้าย เหมือนจุด full stop ในประโยค",
            "tut_syntax_h3_8": "2. ตัวพิมพ์เล็ก-ใหญ่มีผล (Case-Sensitive)",
            "tut_syntax_h3_10": "3. บล็อกด้วย",
            "tut_syntax_p_11": "โค้ดที่อยู่ด้วยกัน (เช่นใน `if` หรือ `loop`) จะอยู่ระหว่างปีกกา",
