            "tut_user_input_h2_147": "ตรวจสอบข้อมูล (อ่านตัวเลข)",
            "tut_user_input_p_148": "ถ้าคุณต้องการคำนวณด้วยค่าที่รับมา คุณต้องแปลงมัน (Casting)",
            "tut_user_input_div_150": "🧠 ความท้าทาย",
