            "adv_memory-experiment_h1_433": "项目：内存实验",
            "adv_memory-experiment_p_436": "别光听我说。自己证明它。",
            "adv_memory-experiment_h2_434": "第 1 部分：“副作用”测试",
            "adv_memory-experiment_p_437": "编写一个执行以下操作的程序：",
            "adv_memory-experiment_li_442": "创建一个带 `Name` 属性的 `class PersonClass`。",
