            "adv_memory-experiment_li_444": "创建一个方法 `ChangeName(object o)` 将名称改为 \"Hacked\"。",
            "adv_memory-experiment_li_445": "为这两种类型调用此方法并打印结果。",
            "adv_memory-experiment_h2_435": "第 2 部分：基准测试 (内存压力)",
