            "adv_plugin-system_h1_449": "项目：插件系统",
            "adv_plugin-system_p_451": "创建一个可以加载尚未编写功能的应用。",
            "adv_plugin-system_h2_450": "任务",
            "adv_plugin-system_li_453": "定义一个带 `void Execute()` 方法的 `ICommand` 接口。",
