            "tut_variables_p_156": "变量是用于存储数据的容器 ('盒子')。",
            "tut_variables_h2_152": "创建变量",
            "tut_variables_p_157": "在 C# 中，您必须始终告诉",
            "tut_variables_h2_153": "关键字",
            "tut_variables_p_158": "如果编译器可以自己猜测类型，您可以",
            "tut_variables_h2_154": "常量",
            "tut_variables_p_159": "如果一个值绝不能改变，请使用",
            "tut_variables_h2_155": "命名约定",
            "tut_variables_p_160": "在 C# 中，我们对您命名事物的方式很严格：",
            "tut_variables_li_3": "使用",
            "tut_variables_div_162": "🧠 练习",
