            "tut_datatypes_pro_tip_text": "C# 默认认为 1.5 是 `double`。你想要 `float` 还是 `decimal`？使用后缀：<br><br><ul><li><code>1.5f</code> = <strong>f</strong>loat</li><li><code>1.5d</code> = <strong>d</strong>ouble（默认）</li><li><code>1.5m</code> = deci<strong>m</strong>al（用于 <strong>M</strong>oney）</li></ul>",
