            "tut_api_h1": "Web APIs (HttpClient)",
            "tut_api_intro": "将你的应用程序连接到互联网并获取实时数据。",
            "tut_api_what_is": "什么是 API？",
            "tut_api_what_is_text": "API (应用程序编程接口) 允许两个应用程序相互通过。通常我们使用返回 JSON 的 **REST API**。",
            "tut_api_httpclient": "HttpClient",
            "tut_api_httpclient_desc": "在 C# 中，我们使用 `HttpClient` 类来发出请求。注意：这是一个“重”对象，请明智地使用它！",
            "tut_api_async": "Async & Await",
            "tut_api_async_desc": "互联网很慢。因此，API 调用总是 **异步** 的。你的程序在等待数据时不应卡死。",
            "tut_api_get_request": "示例：GET 请求",
            "tut_api_get_request_desc": "让我们从公共 API 获取数据。",
